    out = [row[:] for row in grid]
    rows = [r for r in range(h) if any(grid[r][c] == 1 for c in range(w))]
    cols = [c for c in range(w) if any(grid[r][c] == 1 for r in range(h))]
    # The marker pairs define full-width/full-height rays.
    line_cells = set()
    for r in rows:
        for c in range(w):
            line_cells.add((r, c))
            out[r][c] = 1
    for c in cols:
        for r in range(h):
            line_cells.add((r, c))
            out[r][c] = 1
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            comp = []
            hit = False
            while q:
                y, x = q.pop()
                comp.append((y, x))
                hit |= (y, x) in line_cells
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    ny, nx = y+dy, x+dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 2 and (ny,nx) not in seen:
                        seen.add((ny,nx)); q.append((ny,nx))
            if hit:
                for y, x in comp:
                    out[y][x] = 1
    return out
